import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const n="/assets/image-cn2024.Zdn_cQVy.png",l="/assets/image-cn20241.RLeZCYMC.png",s="/assets/image-cn20242.Coe1o9Lo.png",i="/assets/image-cn20243.DL-1Agrr.png",p="/assets/image-cn20244.CDRlMu8n.png",d="/assets/image-20245.GD1nl7Hd.png",c="/assets/image-cn20246.BK4tTcaU.png",m="/assets/image-cn20247.2qxncxCl.png",S=JSON.parse('{"title":"One-click deployment of Palworld on Windows server","description":"","frontmatter":{"title":"One-click deployment of Palworld on Windows server"},"headers":[],"relativePath":"operations-knowledge-base/operating-system/windows/one-click-deployment-of-palworld-on-windows-server.md","filePath":"operations-knowledge-base/operating-system/windows/one-click-deployment-of-palworld-on-windows-server.md","lastUpdated":1794292919000}'),h={name:"operations-knowledge-base/operating-system/windows/one-click-deployment-of-palworld-on-windows-server.md"};function u(w,e,g,y,f,b){return o(),r("div",null,[...e[0]||(e[0]=[a('<p>Deployment Environment</p><ul><li>Server configuration: Take CPU 4 cores and memory 16GB as an example (usually can meet 6-8 people online at the same time)</li><li>Operating System:Windows Server 2019</li></ul><p>Log in to Windows</p><p>1、Log in to the raksmart console and obtain the server‘s login password. If you forget your password, you can reset it in the console:</p><p><img src="'+n+'" alt=""></p><p>2、Use the <em>Remote Desktop Connection</em> on your computer, enter the IP address, port, account, and password to remotely connect to the server.</p><p><img src="'+l+'" alt=""></p><p>Deployment</p><p>Prerequisites: PowerShell</p><p>One-click deployment on Windows requires PowerShell. PowerShell is a task automation and configuration management framework that provides a command-line shell and scripting language for managing and controlling Windows operating systems and related applications. So how do you find PowerShell? Here are somen methods:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>Methods</td><td>Descriptions</td></tr><tr><td>Using the Start Menu</td><td>Click the Windows Start button and type <em>PowerShell</em> in the search box. You should see a search result for <em>Windows PowerShell</em> or <em>PowerShell</em>. Click that result to open PowerShell.</td></tr><tr><td>Using the Run Dialog Box</td><td>Press the <em>Win + R</em> key combination to open the Run dialog box. Enter <em>powershell</em> in the box and click <em>OK</em> to open PowerShell.</td></tr><tr><td>Using File Explorer</td><td>Open File Explorer (Windows Explorer), navigate to the desired directory, then type <em>powershell</em> in the address bar and press <em>Enter</em>. This will open PowerShell in the current directory.</td></tr></tbody></table><p>Step 1: Download the C++ runtime library (click the link to download), which needs to be installed manually. <a href="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Faka.ms%2Fvs%2F17%2Frelease%2Fvc_redist.x64.exe&amp;source=article&amp;objectId=2383611" title="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Faka.ms%2Fvs%2F17%2Frelease%2Fvc_redist.x64.exe&amp;source=article&amp;objectId=2383611" target="_blank" rel="noreferrer">https://aka.ms/vs/17/release/vc_redist.x64.exe</a></p><p>Step 2: Download the DirectX support library (click the link to download), which needs to be installed manually. <a href="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Fwww.microsoft.com%2Fen-us%2Fdownload%2Fdetails.aspx%3Fid%3D35&amp;source=article&amp;objectId=2383611" title="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Fwww.microsoft.com%2Fen-us%2Fdownload%2Fdetails.aspx%3Fid%3D35&amp;source=article&amp;objectId=2383611" target="_blank" rel="noreferrer">https://www.microsoft.com/en-us/download/details.aspx?id=35</a></p><p>Step 3: Run the one-click deployment command</p><p>The one-click deployment method is suitable for developers who want to quickly get started with the Palworld. The deployment can be completed by running only one line of command.</p><p>With reference to the official tutorial, we have packaged a script for one-click deployment of the Palworld for you and uploaded it to the cloud. You only need to log in to the server, copy and run the following command in PowerShell. Usually, after waiting for 3-5 minutes, the deployment can be completed.</p><p>iex (irm &#39;<a href="https://pal.pet/pal-server/Windows/install.ps1" target="_blank" rel="noreferrer">https://pal.pet/pal-server/Windows/install.ps1</a>&#39;)</p><p>⚠️Note: If you use a server in mainland China to run the one-click deployment script, the script may fail to run due to network problems. It is recommended that you retry multiple times or deploy again at a different time. The main reason here is that the installation process requires requesting Steam&#39;s server, and the network connection may be unstable.</p><p>Step 4: Turn off the firewall</p><p><img src="'+s+'" alt=""></p><p>⚠️Note: Be sure to turn off the firewall in the machine, otherwise the server may not be able to be connected.</p><p><strong>Server-side Startup and Restart</strong></p><p>After the server-side deployment is complete, it will start automatically. No additional startup is required.</p><p>After the server restarts, the Palworld server-side will start automatically.</p><p>If you need to restart the server-side, simply restart the server.</p><p>Log in to the game</p><p>Prerequisites</p><ul><li>First you need to download the Steam client-side on your local computer.</li><li>Secondly, you need to <a href="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Fstore.steampowered.com%2Fapp%2F1623730%2FPalworld%2F%3Fl%3Dschinese&amp;source=article&amp;objectId=2382000" title="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Fstore.steampowered.com%2Fapp%2F1623730%2FPalworld%2F%3Fl%3Dschinese&amp;source=article&amp;objectId=2382000" target="_blank" rel="noreferrer">buy Palworld</a>on Steam.</li></ul><p>Login steps</p><p>Step 1: Open the Steam client and log in to your Steam account.</p><p><img src="'+i+'" alt=""></p><p>Step 2: Find the Palworld in the <em>Library</em> and click <em>Start Game</em>.</p><p><img src="'+p+'" alt=""></p><p>Step 3: Select [Join Multiplayer (Dedicated Server)] in the game menu.</p><p><img src="'+d+'" alt=""></p><p>Step 4: At this point, you have successfully built a dedicated server for Palworld. Players can enter the public IP address and port number of the server you have deployed (such as 11.11.11.11:8211). After successfully connecting to the server, they can play online.</p><p>⚠️Note: Remember to use an English colon between the public IP and the port, otherwise you will be prompted<code>Format Error. Example: 127.0.0.1:7777</code>！！！</p><p><img src="'+c+'" alt=""></p><p>Tip: You can check the public IP of the server in the user backend. When entering the server connection address, if your server public IP is displayed as: 175.xxx.xx.138, you need to fill in the following when entering the link:175.xxx.xx.138:8211</p><p>Renew</p><p>Open PowerShell</p><p>Enter the following command</p><p>iex (irm &#39;<a href="https://pal.pet/update%5C_windows.ps1" target="_blank" rel="noreferrer">https://pal.pet/update\\_windows.ps1</a>&#39;)</p><p>Wait for a while and the task will be successfully executed to complete the update.</p><p>Manually configure game parameters</p><p>After the deployment of the Palworld is completed, if you want to DIY the game world according to your own preferences, you need to take the following steps:</p><p>Step 1: Go to the following path to find the configuration file of the game world parameters:<code>PalWorldSettings.ini</code></p><p>C:\\Program Files\\PalServer\\steam\\steamapps\\common\\PalServer\\Pal\\Saved\\Config\\WindowsServer\\PalWorldSettings.ini</p><p><img src="'+m+'" alt=""></p><p>Step 2: Select the file, right-click, and choose Notepad as the opening method.</p><p>Step 3: Write the specific world configuration according to your needs. The following content is only an example. For detailed parameters, please refer to the <a href="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Ftech.palworldgame.com%2Foptimize-game-balance&amp;source=article&amp;objectId=2383611" title="https://cloud.tencent.com/developer/tools/blog-entry?target=https%3A%2F%2Ftech.palworldgame.com%2Foptimize-game-balance&amp;source=article&amp;objectId=2383611" target="_blank" rel="noreferrer">official description</a>。</p><p>Difficulty=None ServerName=Lighthouse ServerDescription=Lighthouse AdminPassword=ABC ServerPassword=TEST DeathPenalty=All bEnablePlayerToPlayerDamage=False</p><p>Step 4: Restart the server to make it effective (Palworld you deployed will start automatically).</p>',53)])])}const F=t(h,[["render",u]]);export{S as __pageData,F as default};
